define('taoQtiItem/qtiCreator/context/qtiCreatorContext',['lodash', 'core/eventifier', 'core/promise', 'taoQtiItem/qtiCreator/context/loader'], function (_, eventifier, Promise, pluginLoader) {
  'use strict';
  return function qtiCreatorContextFactory() {
    var plugins = {};
    var pluginRun = method => {
      var execStack = [];
      _.forEach(plugins, plugin => {
        if (_.isFunction(plugin[method])) {
          execStack.push(plugin[method]());
        }
      });
      return Promise.all(execStack);
    };
    var qtiCreatorContext = {
      init() {
        return pluginLoader.load().then(() => {
          var pluginFactories = pluginLoader.getPlugins();
          _.forEach(pluginFactories, pluginFactory => {
            var plugin = pluginFactory(this);
            plugins[plugin.getName()] = plugin;
          });
          return pluginRun('init').then(() => {
            this.trigger('init');
          });
        }).catch(err => {
          this.trigger('error', err);
        });
      },
      destroy() {
        return pluginRun('destroy').then(() => {
          this.trigger('destroy');
        }).catch(function (err) {
          this.trigger('error', err);
        });
      }
    };
    return eventifier(qtiCreatorContext);
  };
});
