define('taoQtiItem/qtiCreator/helper/popup',['jquery', 'lodash', 'core/dataattrhandler'], function ($, _, dataAttrHandler) {
  'use strict';

  var init = function init($popups, options) {
    var defaults = {
      top: null,
      right: 2,
      title: null
    };
    options = _.assign(defaults, options || {});
    var open = function open($trigger, $popup) {
      var $container = $popup.parents('.sidebar-popup-parent');
      var $actionBar = $('.item-editor-bar');
      var baseOffsetTop = $actionBar.offset().top - $actionBar.height();
      var maxHeight = $(window).height() - baseOffsetTop;
      var top = _.isNull(options.top) ? $trigger.offset().top - baseOffsetTop - $popup.height() / 2 : options.top;
      var $titleArea = $popup.find('.sidebar-popup-title');
      var $title = $titleArea.find('h3');
      if ($titleArea.length) {
        maxHeight -= $titleArea.height();
      }
      $trigger.trigger('beforeopen.popup', {
        popup: $popup,
        trigger: $trigger
      });
      $popup.show();
      $popup.css({
        top: Math.max(baseOffsetTop, top),
        right: $container.hasClass('item-editor-sidebar-wrapper') ? $container.width() + options.right : options.right
      });
      if (options.title) {
        $title.text(options.title);
      }
      $popup.find('.sidebar-popup-content').css({
        maxHeight: maxHeight
      });
      $trigger.trigger('open.popup', {
        popup: $popup,
        trigger: $trigger
      });
    };
    var close = function close($trigger, $popup) {
      $trigger.trigger('beforeclose.popup', {
        popup: $popup,
        trigger: $trigger
      });
      $popup.hide();
      $trigger.trigger('close.popup', {
        popup: $popup,
        trigger: $trigger
      });
    };
    $popups.each(function () {
      var _trigger = $(this),
        $popup = options.popup || function () {
          return dataAttrHandler.getTarget('popup', _trigger);
        }();
      var $closer = $popup.find('.closer'),
        $dragger = $popup.find('.sidebar-popup-title').not($closer);
      if (!$popup || !$popup.length) {
        throw new Error('No popup found');
      }
      if ($closer.length) {
        $closer.on('click', function () {
          close(_trigger, $popup);
        });
      }
      if ($dragger.length) {
        $popup.draggable({
          handle: $dragger
        });
      }
      _trigger.prop('popup', $popup);
    });
    $popups.on('click', function (e) {
      var _trigger = $(e.target),
        $popup = _trigger.prop('popup');
      e.preventDefault();
      if ($popup.is(':visible')) {
        close(_trigger, $popup);
      } else {
        open(_trigger, $popup);
      }
    });
  };
  return {
    init: init
  };
});
